#include <deque>
#include <iostream>

int main() {
    std::deque<int> d;
    // Deque supports O(1) insertion at both ends
    d.push_back(5);
    d.push_front(1);
    d.push_front(0);
    d.push_back(10);

    // d.capacity(); // ERROR: Deque does not support capacity()
    // d.reserve(100); // ERROR: Deque does not support reserve()

    std::cout << "Deque size: " << d.size() << "\n";
    d.pop_front(); // O(1) deletion
    d.pop_back();  // O(1) deletion
}
